const res = $input.first().json;
const items = res.list ?? [];

// Fallback: neueste Opportunity nehmen wenn kein 'Produce Now' vorhanden
if (!items.length) {
  return [{ json: {
    opp_id: null,
    topic: 'KI-Agenten in der Praxis 2026',
    category: 'KI-Tools',
    context: 'Allgemeiner Überblick über KI-Agenten'
  } }];
}

const opp = items[0];
return [{ json: {
  opp_id:   opp.Id,
  topic:    opp.topic ?? opp.title ?? opp.keyword ?? '',
  category: opp.category ?? 'KI-Tools',
  context:  opp.summary ?? opp.description ?? opp.niche_analysis ?? ''
} }];

const gemRes  = $input.first().json;
const rawText = gemRes.candidates?.[0]?.content?.parts?.[0]?.text ?? '{}';
const topic   = $('Research-Prompt bauen').item.json.topic;
const category = $('Research-Prompt bauen').item.json.category;
const oppId   = $('Research-Prompt bauen').item.json.opp_id;

let brief = {};
try {
  const match = rawText.match(/\{[\s\S]*\}/);
  if (match) brief = JSON.parse(match[0]);
} catch(_) {
  brief = { executive_summary: rawText.substring(0, 500) };
}

const pieceId = `research-${Date.now()}`;

return [{ json: {
  piece_id:        pieceId,
  opp_id:          oppId,
  topic,
  category,
  title:           `Research Brief: ${topic}`,
  excerpt:         brief.executive_summary ?? '',
  content_text:    JSON.stringify(brief, null, 2),
  seo_keywords:    brief.seo_keywords ?? '',
  main_thesis:     brief.main_thesis ?? '',
  forecast:        `6M: ${brief.forecast_6_months ?? ''} | 12M: ${brief.forecast_12_months ?? ''}`
} }];
